function RetiredHead() {
  return <th>Retired</th>;
}

// Whether the person is retired and from when, their past retirements (one line each), the date and
// button that retire them (a blank date takes the sheet's today) and the button that unretires them on
// the sheet's today. A refused retirement or unretirement shows its error until the next is tried.
function PersonRetired({ person }: { person: Person }) {
  const [user] = useCurrentUser();
  const [sheet] = useCurrentSheet();
  const [date, setDate] = useState('');
  const queryClient = useQueryClient();

  const retire = useMutation({
    mutationKey: personActionKey(sheet, person.id),
    mutationFn: (from: string) =>
      postJson<Person>(`/api/sheets/${encodeURIComponent(sheet)}/people/${person.id}/retire`, { date: from, user }),
    onSuccess: async () => {
      await Promise.all([
        queryClient.invalidateQueries({ queryKey: peopleKey(sheet) }),
        queryClient.invalidateQueries({ queryKey: poolsKey(sheet) }),
      ]);
      setDate('');
    },
  });

  const unretire = useMutation({
    mutationKey: personActionKey(sheet, person.id),
    mutationFn: () =>
      postJson<Person>(`/api/sheets/${encodeURIComponent(sheet)}/people/${person.id}/unretire`, { user }),
    onSuccess: async () => {
      await Promise.all([
        queryClient.invalidateQueries({ queryKey: peopleKey(sheet) }),
        queryClient.invalidateQueries({ queryKey: poolsKey(sheet) }),
      ]);
    },
  });

  const latest = useLatestPersonAction(sheet, person.id);

  return (
    <td>
      <span data-testid="person-retired">{person.retired ? 'yes' : 'no'}</span>{' '}
      <span data-testid="person-retired-from">{person.retiredFrom ?? ''}</span>{' '}
      {person.pastRetirements.map((r, i) => (
        <div key={i} data-testid="person-retirement-line">
          {r.from} to {r.to}
        </div>
      ))}
      <input
        type="date"
        data-testid="person-retire-date"
        value={date}
        onChange={(e) => {
          retire.reset();
          setDate(e.target.value);
        }}
      />
      <button
        type="button"
 *  `patronIds` are the ids of the other people on the sheet they named as their patrons, in the order they named them.
 *  `grade` is the grade in force on the sheet's today; `grades` every grade with the date it applies from.
 *  `terms` are their own terms in whole days (null when none), ahead of their grade's and the sheet's.
 *  `contact` is their contact (trimmed, lower-cased; null when none), no other person's on the sheet.
 *  `aliases` are other names they are found by (no name or other alias on the sheet), sorted as names are compared.
 *  `clashing` whether their name or an alias is used as a name or alias on another sheet of the sheet's tree (its
 *  ancestors and descendants); every edit of them is refused until it renames them to a name that does not clash.
 *  `origin` is the id of the sheet they were transferred from (null when they were not).
 *  `pastRetirements` are the retirements they were unretired from, oldest first.
 *  `tags` are their tags (trimmed, lower-cased, no repeats), sorted; a claim counts for a tag when it or its
 *  person carries it. */
export type Person = {
  id: number;
  name: string;
  grade: string;
  grades: Grades;
  version: number;
  statementCount: number;
  statedTotal: string | null;
  statementDate: string | null;
  retired: boolean;
  retiredFrom: string | null;
  retiredNow: boolean;
  held: boolean;
  holds: Hold[];
  patronIds: number[];
  terms: number | null;
  contact: string | null;
  aliases: string[];
  clashing: boolean;
  origin: string | null;
  pastRetirements: PastRetirement[];
  tags: string[];
};

/** A past retirement: from the date retired from to the day unretired (yyyy-MM-dd). No claim dated
 *  after its from-date and before its to-date may be added. */
export type PastRetirement = { from: string; to: string };

/** A hold from its from-date to its to-date (yyyy-MM-dd, both inclusive; null for no end). */
export type Hold = { from: string; to: string | null };

/** Whether the hold covers the date (yyyy-MM-dd). */
export const covers = (h: Hold, date: string) => h.from <= date && (h.to === null || date <= h.to);

export const GRADES = ['A', 'B', 'C'] as const;

